// 「OBS の操作」でつないだ OBS を、拡張機能のページとキーから操作する。
(() => {
  const disconnected = "OBS につながっていません（「OBS の操作」でつないでください）";
  const stream = { id: "stream", type: "Stream", name: "配信", version: 0 };
  const record = { id: "record", type: "Record", name: "録画", version: 0 };
  let connected = false, connection = 0, pollTimer, reportTimer, listTimer;
  let streamSample, bitrate = "—", scenes = [], audio = [], currentScene = "";
  let sceneVersion = 0, sceneListVersion = 0, audioListVersion = 0, audioReading;
  let scenesReady = false, audioReady = false;
  const muteEvents = new Map();

  function time(ms) {
    const seconds = Math.floor((ms || 0) / 1000);
    const two = (n) => String(n).padStart(2, "0");
    return Math.floor(seconds / 3600) + ":" + two(Math.floor(seconds / 60) % 60) + ":" + two(seconds % 60);
  }

  function outputButton(output) {
    output.shown = null;
    if (!output.status || output.moving || output.command) return [];
    const active = output.status.outputActive;
    output.shown = active;
    return [{ id: output.id, label: (active ? "■ " : "● ") + output.name + (active ? "を止める" : "を始める"),
      style: active ? "danger" : "primary", confirm: true,
      confirmLabel: "本当に" + output.name + (active ? "を止める？" : "を始める？") + "（もう一度押す）" }];
  }

  function report() {
    if (reportTimer !== undefined) return;
    reportTimer = setTimeout(() => {
      reportTimer = undefined;
      const live = stream.status?.outputActive;
      const streamTime = live ? time(stream.status.outputDuration) : stream.status ? "配信していません" : "—";
      const recording = record.status?.outputActive ?
        (record.status.outputPaused ? "一時停止中 " : "録画中 ") + time(record.status.outputDuration) :
        record.status ? "止まっています" : "—";
      const { outputSkippedFrames = 0, outputTotalFrames = 0 } = stream.status || {};
      const dropped = live && outputTotalFrames > 0 ? 100 * outputSkippedFrames / outputTotalFrames : 0;
      lfx.status({
        level: !connected ? "warn" : live ? "ok" : "",
        text: !connected ? disconnected : live ? "配信中 " + streamTime : stream.status ? streamTime : "配信の状態を確認しています…",
        controls: {
          stream: connected ? [...outputButton(stream), ...outputButton(record)] : [],
          scenes: scenes.map((name) => ({ id: "scene:" + name, label: name, style: name === currentScene ? "active" : "normal" })),
          audio: audio.map(({ name, muted }) => ({ id: "mute:" + name, label: name,
            note: muted ? "ミュート中" : "聞こえています", style: muted ? "danger" : "normal" })),
        },
        stats: {
          time: { text: streamTime },
          bitrate: { text: bitrate },
          dropped: { text: live ? dropped.toFixed(1) + "%" : "—", level: dropped >= 5 ? "err" : dropped >= 1 ? "warn" : "" },
          record: { text: recording },
        },
      });
    }, 120);
  }

  function updateOutput(output, status) {
    output.status = status;
    if (output === stream) {
      const previous = streamSample;
      streamSample = status.outputActive && Number.isFinite(status.outputBytes) ?
        { bytes: status.outputBytes, at: performance.now() } : null;
      const elapsed = streamSample && previous ? streamSample.at - previous.at : 0;
      bitrate = elapsed > 0 && streamSample.bytes >= previous.bytes ?
        Math.round((streamSample.bytes - previous.bytes) * 8 / elapsed) + " kbps" : "—";
    }
    if (output.moving && (output.moving.target === status.outputActive || performance.now() >= output.moving.until)) output.moving = null;
    report();
  }

  async function readOutput(output) {
    if (output.reading) return;
    const session = connection, version = output.version;
    const reading = {};
    output.reading = reading;
    const result = await lfx.obs("Get" + output.type + "Status");
    if (output.reading === reading) output.reading = null;
    if (session === connection && version === output.version && result.ok) updateOutput(output, result.data);
  }

  function updateActions() {
    if (!scenesReady || !audioReady) return;
    const actions = [...scenes.map((name) => ({ id: "scene:" + name, label: "シーン：" + name })),
      ...audio.map(({ name }) => ({ id: "mute:" + name, label: name + "のミュートを切り替える" }))].slice(0, 50);
    void lfx.setActions(actions.map((action) => ({ ...action, label: action.label.slice(0, 120) })));
  }

  // 名前は OBS にそのまま送り返せる長さのものを使う。
  const validName = (name) => typeof name === "string" && name.trim() && name.length <= 1018 && !/[\x00-\x1f\x7f]/.test(name);
  async function readScenes() {
    const version = ++sceneListVersion, activeVersion = sceneVersion;
    const result = await lfx.obs("GetSceneList");
    if (!connected || version !== sceneListVersion || !result.ok) return;
    scenes = [...new Set(result.data.scenes.map((scene) => scene.sceneName).filter(validName).reverse())].slice(0, 60);
    if (activeVersion === sceneVersion) currentScene = result.data.currentProgramSceneName;
    scenesReady = true;
    updateActions();
    report();
  }

  async function readAudio() {
    if (audioReading) return;
    const reading = {};
    audioReading = reading;
    const version = audioListVersion;
    const current = () => connected && version === audioListVersion;
    const next = await listAudio(current);
    if (audioReading !== reading) return;
    audioReading = null;
    if (!current()) {
      clearTimeout(listTimer);
      listTimer = setTimeout(readAudio, 150);
      return;
    }
    if (!next) return;
    audio = next.slice(0, 60).map(({ name, muted, before }) => {
      const latest = muteEvents.get(name);
      return { name, muted: latest && latest !== before ? latest.muted : muted };
    });
    audioReady = true;
    updateActions();
    report();
  }

  async function listAudio(current) {
    const [inputs, special] = await Promise.all([lfx.obs("GetInputList"), lfx.obs("GetSpecialInputs")]);
    if (!current() || !inputs.ok || !special.ok) return;
    const preferred = Object.values(special.data).filter(validName);
    const typical = /audio|wasapi|pulse|coreaudio|pipewire/i;
    for (const input of inputs.data.inputs) {
      if (typical.test(input.unversionedInputKind || input.inputKind)) preferred.push(input.inputName);
    }
    // 動画やブラウザなどにも音がある。ミュート状態を読める入力だけを並べる。
    const candidates = [...new Set([...preferred, ...inputs.data.inputs.map((input) => input.inputName)].filter(validName))];
    const next = [];
    for (let offset = 0; offset < candidates.length && next.length < 60 && current(); offset += 12) {
      const batch = await Promise.all(candidates.slice(offset, offset + 12).map(async (name) => {
        const before = muteEvents.get(name);
        const result = await lfx.obs("GetInputMute", { inputName: name });
        if (result.ok && typeof result.data.inputMuted === "boolean") return { name, before, muted: result.data.inputMuted };
      }));
      next.push(...batch.filter(Boolean));
    }
    return next;
  }

  function muteChanged(name, muted) {
    muteEvents.set(name, { muted });
    const input = audio.find((item) => item.name === name);
    if (input) { input.muted = muted; report(); }
  }

  function changeConnection(value) {
    connected = value;
    connection++;
    sceneListVersion++;
    audioListVersion++;
    clearInterval(pollTimer);
    clearTimeout(listTimer);
    scenes = []; audio = []; currentScene = "";
    scenesReady = audioReady = false;
    audioReading = null;
    muteEvents.clear();
    streamSample = null; bitrate = "—";
    for (const output of [stream, record]) {
      output.status = output.command = output.moving = output.reading = output.shown = null;
    }
    report();
    if (!connected) return;
    void readOutput(stream);
    void readOutput(record);
    void readScenes();
    void readAudio();
    pollTimer = setInterval(() => {
      for (const output of [stream, record]) {
        if (!output.status || output.status.outputActive || output.moving) void readOutput(output);
      }
    }, 1000);
  }

  function outputEvent(output, { outputActive, outputState }) {
    output.version++;
    if (outputState === "OBS_WEBSOCKET_OUTPUT_STARTING" || outputState === "OBS_WEBSOCKET_OUTPUT_STOPPING") {
      output.moving = { target: outputState === "OBS_WEBSOCKET_OUTPUT_STARTING", until: performance.now() + 15000 };
    } else if (!outputState || /_(STARTED|STOPPED|PAUSED|RESUMED|RECONNECTED)$/.test(outputState)) {
      output.moving = null;
      const active = outputState === "OBS_WEBSOCKET_OUTPUT_PAUSED" || outputActive === true;
      output.status = { ...(active && output.status?.outputActive ? output.status : {}), outputActive: active,
        outputPaused: outputState === "OBS_WEBSOCKET_OUTPUT_PAUSED" };
      if (!active && output === stream) { streamSample = null; bitrate = "—"; }
    }
    report();
  }

  lfx.onObs((message) => {
    if (message.type === "connection") { changeConnection(message.connected); return; }
    const { eventType, data } = message;
    if (eventType === "StreamStateChanged") outputEvent(stream, data);
    else if (eventType === "RecordStateChanged") outputEvent(record, data);
    else if (eventType === "CurrentProgramSceneChanged") { sceneVersion++; currentScene = data.sceneName; report(); }
    else if (eventType === "SceneListChanged") void readScenes();
    else if (eventType === "InputMuteStateChanged") muteChanged(data.inputName, data.inputMuted);
    else {
      muteEvents.delete(data.oldInputName ?? data.inputName);
      audioListVersion++;
      clearTimeout(listTimer);
      listTimer = setTimeout(readAudio, 150);
    }
  });

  async function toggle(output) {
    if (!output.status || output.moving || output.command) return { ok: false, error: output.name + "の状態を確認しています" };
    const session = connection, version = output.version, active = output.status.outputActive;
    const changed = { ok: false, error: output.name + "の状態が変わりました。もう一度操作してください" };
    if (output.shown !== active) return changed;
    const command = {};
    output.command = command;
    try {
      const current = await lfx.obs("Get" + output.type + "Status");
      if (!current.ok) return current;
      if (session !== connection) return { ok: false, error: disconnected };
      if (version !== output.version || current.data.outputActive !== active) {
        if (version === output.version) updateOutput(output, current.data);
        return changed;
      }
      const result = await lfx.obs((active ? "Stop" : "Start") + output.type);
      if (result.ok && session === connection && version === output.version) {
        output.moving = { target: !active, until: performance.now() + 15000 };
      }
      return result;
    } finally {
      if (output.command === command) output.command = null;
      report();
    }
  }

  lfx.onCommand(async (id) => {
    if (!connected) return { ok: false, error: disconnected };
    if (id === "stream") return toggle(stream);
    if (id === "record") return toggle(record);
    if (id.startsWith("scene:") && scenes.includes(id.slice(6))) {
      return lfx.obs("SetCurrentProgramScene", { sceneName: id.slice(6) });
    }
    if (id.startsWith("mute:") && audio.some((item) => item.name === id.slice(5))) {
      return lfx.obs("ToggleInputMute", { inputName: id.slice(5) });
    }
    return { ok: false, error: "この操作を使えません" };
  });
  report();
})();
